/* ================= Kapitel 6–8 ================= */
Object.assign(CHAPTERS.find(c=>c.n===6),{title:"Neoklassische Gegenrevolution und Neue Neoklassische Synthese", teaser:"Phillips-Kurve, Monetarismus, NAIRU, Inflation Targeting und Angebotspolitik."});
Object.assign(CHAPTERS.find(c=>c.n===7),{teaser:"Hysterese, Grenzen der Geldpolitik, Einkommenspolitik und das Kostenparadox."});
Object.assign(CHAPTERS.find(c=>c.n===8),{title:"Spielarten des Kapitalismus und Wachstumsmodelle", teaser:"Koordinierte und liberale Marktwirtschaften, lohn-, schulden- und exportgetriebenes Wachstum."});

LESSONS[6]=[
{id:"6-1", t:"Der Dauerstreit: Inflation und Arbeitslosigkeit", html:`
<p>Übersteigt die Nachfrage den Vollbeschäftigungsoutput länger, setzen Arbeitnehmer:innen höhere Löhne und Unternehmen höhere Preise durch. Im Extremfall entstehen <b>Lohn-Preis-Spiralen</b>, die schwer zu stoppen sind. Umgekehrt führt dauerhafter Nachfragemangel zu <b>Deflation</b>, die noch schwerer zu bekämpfen ist.</p>
<table class="kv">
<tr><td>Inflation</td><td>Angebotskrise nach dem Ersten Weltkrieg und Ruhrbesetzung (bis 1923), Stagflation nach den Ölpreisschocks der 1970er, Corona- und Energiekrise der frühen 2020er</td></tr>
<tr><td>Deflation</td><td>Weltwirtschaftskrise Anfang der 1930er, Japan nach 1991, Eurokrise Anfang der 2010er</td></tr></table>
<p>Keynes war wenig um Inflation besorgt; in den 1930ern herrschte Deflation. Die Gegenrevolution nach ihm entzündete sich genau an der Frage, wie Arbeitslosigkeit und Inflation zusammenhängen.</p>`,
check:[{q:"Welches Ereignis ist ein Beispiel für Stagflation?", o:["Weltwirtschaftskrise 1929","Ölpreisschocks der 1970er Jahre","Japan nach 1991","Eurokrise 2010"], a:1, ex:"Stagflation heißt Stillstand (Stagnation) und Inflation gleichzeitig, so nach den Ölpreisschocks der 1970er.", w:["Die Weltwirtschaftskrise war deflationär: Die Preise fielen.", null, "Japan erlebte nach 1991 Deflation, keine Inflation.", "In der Eurokrise drohte eher Deflation."]}]},
{id:"6-2", t:"Neoklassische Synthese und Phillips-Kurve", html:`
<p>Nach dem Zweiten Weltkrieg bis Anfang der 1970er war die <b>Neoklassische Synthese</b> der Mainstream (Paul Samuelson, John Hicks; Nixon 1972: „We are all Keynesians now“). Ihre Grundlage:</p>
<div class="dlist"><b>Langfristig</b><span>Bei flexiblen Löhnen, Preisen und Zinsen gelten neoklassische Prinzipien (S bestimmt I).</span><b>Kurzfristig</b><span>Es gilt die keynesianische Theorie.</span></div>
<p>Kernstück ist die <b>Phillips-Kurve</b>. Je geringer die Arbeitslosigkeit, desto schneller steigen …</p>
${cmp([["","Ursprüngliche Phillips-Kurve","Modifizierte Phillips-Kurve"],["… was?","die Nominallöhne","die Preise, π = f(U)"]])}
<div class="merk"><b>„5 % Inflation sind mir lieber als 5 % Arbeitslosigkeit“</b>Helmut Schmidt. Die Idee: Die Politik kann zwischen Arbeitslosigkeit und Inflation wählen, je nach Präferenzen. Wer Arbeitslosigkeit für schädlicher hält, nimmt mehr Inflation in Kauf. Genau diesen dauerhaften Zielkonflikt bestritten später Monetarismus und Neuklassik.</div>`,
check:[{q:"Was besagt die modifizierte Phillips-Kurve?", o:["Je höher die Arbeitslosigkeit, desto höher die Inflation","Je geringer die Arbeitslosigkeit, desto höher die Inflation","Inflation und Arbeitslosigkeit sind unabhängig","Die Löhne sinken bei Vollbeschäftigung"], a:1, ex:"Je geringer die Arbeitslosigkeit, desto höher die Inflation: π = f(U). Daraus folgt ein Zielkonflikt zwischen beiden.", w:["Richtung verdreht: Hohe Arbeitslosigkeit dämpft Löhne und Preise.", null, "Unabhängig sind sie erst langfristig laut Monetarismus (vertikale Kurve), nicht in der Phillips-Kurve selbst.", "Bei Vollbeschäftigung steigen die Löhne eher, weil Arbeitskräfte knapp sind."]}]},
{id:"6-3", t:"Monetarismus und Neuklassik: natürliche Arbeitslosigkeit", html:`
<p>Seit den 1960ern einflussreich in den USA, Großbritannien, Chile und Deutschland: Milton Friedman, Robert Lucas, die „Chicago Boys“ in Chile, die monetaristische Tradition der Bundesbank. Sie liefern eine Theorie der <b>Stagflation</b>.</p>
<ul><li>Der Phillips-Kurven-Zusammenhang gilt nur kurzfristig.</li>
<li>Langfristig ist die Phillips-Kurve <b>vertikal</b>: Es gibt eine „natürliche Arbeitslosigkeit“, bedingt durch zu hohe Löhne oder Arbeitsmarktrigiditäten. Später heißt sie <b>NAIRU</b> (non-accelerating inflation rate of unemployment).</li></ul>
<h3>Der Mechanismus nach Friedman</h3>
<ol class="steps"><li>Arbeitnehmer:innen arbeiten mehr, weil sie glauben, die Reallöhne stiegen.</li><li>Die Unternehmen erhöhen aber die Preise, die Reallöhne bleiben konstant.</li><li>Die höhere Inflation wird für die Zukunft erwartet. Die Arbeitnehmer:innen fordern höhere Nominallöhne.</li><li>Die kurzfristige Phillips-Kurve verschiebt sich nach oben. Um sie erneut zu „täuschen“, müsste die Inflation noch höher sein.</li></ol>
<div class="merk"><b>Folgerung</b>Langfristig bringt Nachfragesteuerung über Geld- und Fiskalpolitik nichts außer Inflation. Stattdessen soll die Inflation stabilisiert und der Arbeitsmarkt flexibilisiert werden, damit sich das Arbeitsangebot nach rechts verschiebt.</div>`,
check:[{q:"Wie verläuft die langfristige Phillips-Kurve laut Monetarismus?", o:["Fallend","Steigend","Vertikal bei der natürlichen Arbeitslosigkeit","Waagerecht"], a:2, ex:"Vertikal bei der natürlichen Arbeitslosigkeit (NAIRU): Langfristig gibt es keinen Zielkonflikt, nur höhere Inflation.", w:["Fallend ist die kurzfristige Phillips-Kurve.", "Eine steigende Kurve kommt in diesem Modell nicht vor.", null, "Waagerecht hieße: Die Arbeitslosigkeit ändert sich, die Inflation nie. Das Gegenteil ist der Fall."]}]},
{id:"6-4", t:"Lohnsetzung, Preissetzung und Lohn-Preis-Spirale", html:`
<p>Das Arbeitsmarktmodell der Vorlesung hat den Reallohn w/p auf der y-Achse und das Arbeitsvolumen E auf der x-Achse:</p>
<ul><li><b>Lohnsetzung</b> (steigend): Je höher die Beschäftigung, desto höhere Reallöhne fordern die Arbeitnehmer:innen, weil sie weniger Angst vor Arbeitslosigkeit haben.</li>
<li><b>Preissetzung</b> (waagerecht): der Reallohn, den die Unternehmen über ihre Preissetzung zu zahlen bereit sind.</li></ul>
<p>Im Schnittpunkt liegt das Gleichgewicht, die NAIRU. Ist die Beschäftigung höher, klafft eine <b>Lücke</b>: Die Arbeitnehmer:innen wollen einen höheren Reallohn, als die Unternehmen zahlen wollen. Sie fordern die erwartete Inflation plus die Lücke, die Unternehmen erhöhen die Preise entsprechend:</p>
${cmp([["Periode","Erwartet","Lücke","Löhne","Preise"],["0","4","0","4","4"],["1","4","2","6","6"],["2","6","2","8","8"],["3","8","2","10","10"]])}
<p class="small muted">Alle Werte in %. Erwartet = erwartete Inflation, Löhne und Preise = Anstieg in dieser Periode.</p>
<p>Die Inflation beschleunigt sich, die Reallöhne bleiben gleich. Liegt die Beschäftigung unter dem Gleichgewicht (Lücke −2 %), sinkt die Inflation von Periode zu Periode bis in die Deflation.</p>
{{fig:g6a}}
<div class="merk"><b>Klausur 2024, 7 Punkte</b>Führt ein Konjunkturprogramm zu Y* > Y<sub>POT</sub>, liegt die Beschäftigung rechts vom Gleichgewicht. Auf dem Arbeitsmarkt klafft die Lücke zwischen Lohn- und Preissetzung, in der Phillips-Kurven-Grafik verschiebt sich die kurzfristige Kurve Periode für Periode nach oben: steigende Inflation.</div>`,
check:[
 {q:"Inflation 2 %, ab t1 Lücke von 2 %. Wie stark steigen die Preise in t2?", o:["2 %","4 %","6 %","8 %"], a:2, ex:"t1: 2 + 2 = 4 %. t2: 4 + 2 = 6 %. Jede Periode kommt die Lücke auf die Inflation der Vorperiode.", w:["2 % ist die Ausgangsinflation, die Lücke fehlt.", "4 % ist die Inflation in t1, gefragt ist t2.", null, "8 % wäre die Inflation in t3."]},
 {q:"Was passiert in der Lohn-Preis-Spirale mit den Reallöhnen?", o:["Sie steigen um die Lücke","Sie bleiben konstant","Sie sinken","Sie steigen mit der Inflation"], a:1, ex:"Die Unternehmen geben jede Lohnsteigerung an die Preise weiter.", w:["Die Arbeitnehmer:innen fordern die Lücke, die Unternehmen erhöhen aber die Preise genauso stark.", null, "Sie sinken nicht: Löhne und Preise steigen gleich schnell.", "Die Nominallöhne steigen mit der Inflation, die Reallöhne gerade nicht."]}
]},
{id:"6-5", t:"„Irrelevanz der Wirtschaftspolitik“", html:`
<p>Monetarismus und Neuklassik folgern:</p>
<ul><li>Keine diskretionäre Konjunkturpolitik, stattdessen <b>regelgebundene</b> Wirtschaftspolitik.</li>
<li><b>Ricardianische Äquivalenz</b>: Erhöht der Staat sein Defizit, sparen die Privaten im gleichen Umfang mehr, weil sie künftige Steuererhöhungen erwarten. Kein Nachfrageeffekt, der Multiplikator ist null oder sehr klein.</li>
<li>Geld- und Fiskalpolitik sollen auch kurzfristig nicht aktiv stabilisieren.</li>
<li>Arbeits-, Güter- und Finanzmärkte sollen flexibilisiert werden.</li></ul>
<p>Die Neuklassik arbeitet mit <b>rationalen Erwartungen</b> und allgemeiner Gleichgewichtstheorie. Das Lehrbuch-Bild der Vorlesung: Wirtschaftspolitik kann die Menschen nicht systematisch täuschen.</p>`,
check:[{q:"Warum ist der Multiplikator nach der Ricardianischen Äquivalenz nahe null?", o:["Weil die Zinsen sinken","Weil Haushalte für erwartete Steuererhöhungen mehr sparen","Weil Importe steigen","Weil der Staat spart"], a:1, ex:"Der höhere Staatskonsum wird durch geringeren privaten Konsum ausgeglichen.", w:["Über die Zinsen sagt die These nichts.", null, "Importe spielen bei der Ricardianischen Äquivalenz keine Rolle.", "Der Staat spart gerade nicht, er macht ein Defizit."]}]},
{id:"6-6", t:"Neuer Konsens und Inflation Targeting", html:`
<p>Seit den 1980ern ist die <b>Neue Neoklassische Synthese</b> (Neukeynesianismus, Neuer Konsens) internationaler Mainstream: Gregory Mankiw, anfangs Joseph Stiglitz und Paul Krugman, Ben Bernanke. Sie übernimmt die Methode der Neuklassik (rationale Erwartungen), kommt aber zu ähnlichen Schlüssen wie die alte Synthese:</p>
<ul><li>Langfristig: neoklassisch, Beschäftigung und Produktion werden am Arbeitsmarkt bestimmt.</li>
<li>Kurzfristig: keynesianisch, aktive Konjunkturpolitik ist nötig, vor allem über die Geldpolitik.</li></ul>
<div class="eq">Y* = 1/(1 − c₁) · (c₀ − c₁T + d − n·i + G)   (kurzfristig)</div>
<div class="eq">Y* = Y<sub>POT</sub>   (langfristig)</div>
<p>Im langfristigen Gleichgewicht muss das BIP dem Potenzial entsprechen, sonst droht eine Inflations- oder Deflationsspirale. Die Zentralbank soll den Zins so wählen, dass Y* = Y<sub>POT</sub>. Ihre Zinsregel:</p>
<div class="eq">i<sub>t</sub> = i<sub>t−1</sub> + k · (π<sub>t−1</sub> − π<sup>T</sup>),   k > 0</div>
<p>War die Inflation über dem Ziel, steigt der Zins, sonst sinkt er, bis das Ziel erreicht und die Output-Lücke geschlossen ist.</p>
${bsp("Beispiel",[["Gegeben","alter Zins 3 %, k = 0,5, Inflation 1 %, Ziel 2 %"],["Rechnung","$ i = 3 % + 0,5 · (1 % − 2 %) = 2,5 %"],["Deutung","Die Inflation liegt unter dem Ziel, also senkt die Zentralbank den Zins."]])}
<div class="merk"><b>Wirtschaftspolitik vor der Finanzkrise</b><ul style="margin:.3em 0"><li>Angebotsorientierung: Flexibilisierung von Güter-, Arbeits- und Finanzmärkten</li><li>Passive Fiskalpolitik: Stabilitätspakt, Schuldenbremse</li><li>Aktive Konjunktursteuerung über ein Inflationsziel <span class="pz">(Inflation Targeting)</span>: Die EZB zielt auf eine Inflation unter, aber nahe 2 %.</li></ul> In einer Währungsunion ist länderspezifische Nachfragesteuerung über die Geldpolitik nicht möglich, diese Rolle müsste die Fiskalpolitik übernehmen.</div>`,
check:[
 {q:"i(t−1) = 2 %, k = 1, Inflation 4 %, Ziel 2 %. Welchen Zins setzt die Zentralbank?", o:["2 %","3 %","4 %","6 %"], a:2, ex:"i = 2 + 1 · (4 − 2) = 4 %.", w:["2 % ist der alte Zins. Weil die Inflation über dem Ziel liegt, muss er steigen.", "3 % entsteht, wenn man nur die halbe Abweichung addiert. Bei k = 1 zählt sie voll.", null, "6 % = 2 + 4: Addiert wird die Abweichung vom Ziel (4 − 2), nicht die ganze Inflation."]},
 {q:"Welche Rolle hat die Fiskalpolitik im Neuen Konsens?", o:["Aktive Konjunktursteuerung","Eher passiv, regelgebunden","Sie setzt das Inflationsziel","Sie bestimmt das Potenzial"], a:1, ex:"Eher passiv und regelgebunden (Stabilitätspakt, Schuldenbremse). Die Konjunktursteuerung übernimmt die Geldpolitik.", w:["Aktive Konjunktursteuerung übernimmt im Neuen Konsens die Geldpolitik.", null, "Das Inflationsziel setzt die Zentralbank, etwa die EZB.", "Das Potenzial wird langfristig am Arbeitsmarkt bestimmt."]}
]},
{id:"6-7", t:"Angebotspolitik", html:`
<p>Im Neuen Konsens ist mehr Beschäftigung ohne Inflation nur möglich, wenn sich das Arbeitsmarktgleichgewicht verschiebt. Zwei Wege:</p>
<p><b>1. Bei der Lohnsetzung ansetzen</b>: Deregulierung des Arbeitsmarkts, also geringere Arbeitslosenunterstützung, weniger allgemeinverbindliche Flächentarifverträge. Die Lohnsetzungsmacht der Gewerkschaften wird geschwächt, die Lohnsetzungskurve verschiebt sich nach rechts, ebenso die langfristige Phillips-Kurve. Höhere Nachfrage ist nun ohne Inflation möglich (Y<sub>POT</sub> steigt).</p>
{{fig:g6b}}
<p><b>2. Bei der Preissetzung ansetzen</b>: Die Preissetzungskurve verschiebt sich nach oben, etwa durch bessere Ausbildung und höhere Produktivität (Arbeitgeber:innen zahlen höhere Reallöhne) oder mehr Wettbewerb auf dem Gütermarkt (niedrigere Preise).</p>
<div class="merk"><b>Unterscheide</b>Neoklassische Arbeitslosigkeit muss auf dem Arbeitsmarkt bekämpft werden. Keynesianische Arbeitslosigkeit entsteht durch zu geringe Güternachfrage im Vergleich zum Vollbeschäftigungsoutput und wird über die Nachfrage bekämpft.</div>`,
check:[{q:"Wie wirkt eine Deregulierung des Arbeitsmarkts im Neuen Konsens?", o:["Lohnsetzung verschiebt sich nach rechts, Potenzial steigt","Preissetzung sinkt","Die Inflation steigt dauerhaft","Die kurzfristige Phillips-Kurve wird vertikal"], a:0, ex:"Die Lohnsetzungsmacht sinkt, die Lohnsetzungskurve verschiebt sich nach rechts. Die NAIRU sinkt, mehr Beschäftigung ohne steigende Inflation ist möglich.", w:[null, "Die Preissetzung ändert sich über Produktivität oder Wettbewerb, nicht über Deregulierung.", "Im Gegenteil: Mehr Beschäftigung wird ohne steigende Inflation möglich.", "Vertikal ist nur die langfristige Phillips-Kurve. Sie verschiebt sich nach rechts."]}]}
];

LESSONS[7]=[
{id:"7-1", t:"Postkeynesianismus im Überblick", html:`
<p>Begründet von Keynes' Kolleg:innen und Nachfolger:innen in Cambridge (Joan Robinson, Nicholas Kaldor) in den 1950er und 1960er Jahren, aufbauend auf Keynes und Michał Kalecki.</p>
<ul><li>Kritik am „Bastard-Keynesianismus“ der Neoklassischen Synthese und des Neuen Konsenses</li>
<li>Nachfrage ist kurz- <b>und</b> langfristig relevant (Hysterese)</li>
<li>Zweifel an der Wirksamkeit der Geldpolitik</li>
<li><b>Functional Finance</b>: zentrale Rolle der Fiskalpolitik gegen Arbeitslosigkeit, Staatsverschuldung ist kein Hindernis für Vollbeschäftigungspolitik</li>
<li>Expliziter Zusammenhang von Verteilung zwischen Klassen (Arbeiter:innen, Kapitalist:innen) und Nachfrage bzw. Wachstum</li>
<li>„Soziologischer“ Blick: Konventionen, fundamentale Unsicherheit, Erwartungen, Machtverhältnisse, Institutionen</li></ul>
<p>Auch neukeynesianische Ökonom:innen entdecken diese Konzepte zunehmend wieder.</p>`,
check:[{q:"In welchen Zeithorizonten ist die Nachfrage aus postkeynesianischer Sicht relevant?", o:["Nur kurzfristig","Nur langfristig","Kurz- und langfristig","Gar nicht"], a:2, ex:"Kurz- und langfristig: Über Hysterese prägt die Nachfrage auch das Produktionspotenzial.", w:["Nur kurzfristig ist die Sicht des Neuen Konsenses. Genau das kritisiert der Postkeynesianismus als „Bastard-Keynesianismus“.", "Die kurze Frist zählt auch: Dort entsteht der Nachfragemangel.", null, "Die Nachfrage steht im Zentrum des Postkeynesianismus."]}]},
{id:"7-2", t:"Zweifel an der Geldpolitik", html:`
<p>Investitions- und Konsumentscheidungen hängen weniger vom Zentralbankzins ab als von</p>
<ul><li>den animal spirits der Unternehmen,</li><li>sozialen Normen,</li><li>Institutionen,</li><li>der Einkommensverteilung.</li></ul>
<p>Dazu kommen die Grenzen aus dem Kapitel zur Geld- und Fiskalpolitik: In der <b>Nominalzinsfalle</b> ist der Realzins trotz Nullzins zu hoch, in der <b>Investitionsfalle</b> reagieren die Investitionen nicht auf den Zins. Dann hilft nur Fiskalpolitik.</p>
<div class="merk"><b>Kein sicherer Kompass</b>Eine seriöse Messung der Output-Lücke als Orientierung für die Geldpolitik ist unmöglich, weil das Potenzial selbst von der Nachfrage abhängt (Hysterese).</div>`,
check:[{q:"Warum ist die Output-Lücke aus postkeynesianischer Sicht kein sicherer Kompass?", o:["Weil das BIP nicht gemessen wird","Weil das Potenzial wegen Hysterese selbst von der Nachfrage abhängt","Weil die Zentralbank sie geheim hält","Weil sie immer null ist"], a:1, ex:"Das Potenzial hängt über Hysterese selbst von der Nachfrage ab. Schätzungen des Potenzials folgen deshalb dem tatsächlichen BIP.", w:["Das BIP wird gemessen. Nicht beobachtbar ist das Potenzial.", null, "Die Lücke ist nicht geheim, sondern geschätzt, und die Schätzung ist das Problem.", "Die Lücke ist nicht immer null, sie ist nur schwer zu messen."]}]},
{id:"7-3", t:"Hysterese am Arbeitsmarkt", html:`
<p><b>Hysterese</b> (griechisch hysteros, später): Der Zustand eines Systems hängt nicht nur von der aktuellen Eingangsgröße ab, sondern auch von seinem früheren Zustand. Einfach gesagt: Ein Zustand dauert fort, auch wenn die Anregung weggefallen ist.</p>
<p>Am Arbeitsmarkt: Zunächst liegt keynesianische Arbeitslosigkeit vor, die Güternachfrage ist zu gering (Y* < Y<sub>POT</sub>). Hält das länger an,</p>
<ul><li>verschiebt sich die <b>Lohnsetzung nach oben</b>, weil Langzeitarbeitslose den Bezug zur Arbeitswelt verlieren und keinen Lohndruck mehr auf Beschäftigte ausüben,</li>
<li>verschiebt sich die <b>Preissetzung nach unten</b>, weil die Arbeitsproduktivität wegen unterlassener Investitionen in den Kapitalstock fällt.</li></ul>
{{fig:g7a}}
<p>Im Ergebnis sinkt die gleichgewichtige Beschäftigung, das Produktionspotenzial fällt, der Deflationsdruck nimmt ab. Kurzfristiger Nachfragemangel führt zu langfristigen Produktionseinbußen. Langfristig wird jedes Arbeitsmarktgleichgewicht möglich. Das gilt analog für „zu hohe“ Nachfrage: Ein Boom kann das Potenzial erhöhen.</p>
<div class="merk"><b>Klausur 2024 (Zweittermin), 7 Punkte</b>„Zeigen Sie grafisch, wie laut Postkeynesianismus Hysterese am Arbeitsmarkt entstehen kann, wenn die Güternachfrage zu lange unter dem ursprünglichen Potenzialoutput liegt.“ Genau diese Grafik.</div>`,
check:[
 {q:"Warum verschiebt sich bei Hysterese die Preissetzungskurve nach unten?", o:["Weil die Gewerkschaften stärker werden","Weil die Produktivität wegen unterlassener Investitionen fällt","Weil die Zinsen steigen","Weil die Preise sinken"], a:1, ex:"Ohne Investitionen sinkt die Produktivität. Die Unternehmen können dann nur noch niedrigere Reallöhne zahlen.", w:["Gewerkschaften spielen bei der Lohnsetzung eine Rolle, nicht bei der Preissetzung.", null, "Zinsen kommen in diesem Diagramm nicht vor.", "Die Kurve zeigt den Reallohn, den die Unternehmen zahlen können. Er sinkt, weil die Produktivität fällt."]},
 {q:"Warum verschiebt sich die Lohnsetzungskurve nach oben?", o:["Langzeitarbeitslose üben keinen Lohndruck mehr aus","Mindestlöhne steigen","Die Inflation steigt","Mehr Menschen suchen Arbeit"], a:0, ex:"Langzeitarbeitslose verlieren den Bezug zur Arbeitswelt und konkurrieren nicht mehr um Stellen. Die Beschäftigten fordern deshalb bei gleicher Beschäftigung höhere Löhne.", w:[null, "Mindestlöhne kommen in der Hysterese-Erklärung nicht vor.", "Die Lohnsetzung zeigt Reallöhne. Inflation verschiebt sie nicht.", "Mehr Arbeitsuchende würden den Lohndruck erhöhen, die Kurve also eher nach unten schieben."]}
]},
{id:"7-4", t:"Hysterese durch falsche Diagnose", html:`
<p>Im Abschwung fällt das Wachstum, Defizit und Arbeitslosigkeit steigen. Ist das ein <b>strukturelles</b> <span class="pz">(dauerhaftes Angebotsproblem)</span> oder ein <b>konjunkturelles</b> <span class="pz">(vorübergehende Nachfrageschwäche)</span> Problem?</p>
<ol class="steps"><li>Die Politik hält ein konjunkturelles Problem fälschlich für strukturell.</li><li>Sie reagiert mit Deregulierung und Sparpolitik <span class="pz">(Austerität)</span>.</li><li>Es entsteht Hysterese: Das ursprünglich konjunkturelle Problem wird durch die falsche Politik zu einem strukturellen.</li></ol>
<h3>Das Randwertproblem</h3>
<p>Potenzial und NAIRU werden aus dem beobachteten BIP und der beobachteten Arbeitslosigkeit geschätzt. Am aktuellen Rand ist unklar, ob man den alten Trend fortschreibt oder ihn an die neuen Daten anpasst. Passt man an, erscheint ein Abschwung strukturell:</p>
<ul><li>Das geschätzte Potenzial sinkt mit.</li><li>Die Output-Lücke schrumpft.</li><li>Das strukturelle Defizit wächst.</li></ul>
<div class="merk"><b>Beispiel Spanien</b>Die EU-Kommission schätzte, dass die strukturelle Arbeitslosigkeit (NAWRU) von unter 10 % (2007) auf über 25 % (2013) stieg. Fast die ganze Arbeitslosigkeit galt damit als strukturell, Arbeitsmarktreformen und Sparprogramme wurden gefordert. Schreibt man die NAWRU dagegen fort, wäre der Anstieg konjunkturell gewesen und hätte Konjunkturprogramme gerechtfertigt.</div>`,
check:[{q:"Was ist das Randwertproblem?", o:["Die Zentralbank kann den Zins nicht unter null senken","Potenzial und NAIRU am aktuellen Rand hängen davon ab, ob man den Trend fortschreibt oder anpasst","Die Leistungsbilanz der Welt ist null","Das BIP misst keine Sorgearbeit"], a:1, ex:"Je nach Methode erscheint derselbe Abschwung konjunkturell oder strukturell.", w:["Das ist die Nominalzinsfalle.", null, "Das ist die Salden-Identität für die Welt.", "Das ist die feministische BIP-Kritik."]}]},
{id:"7-5", t:"Eine postkeynesianische Phillips-Kurve", html:`
<p>Postkeynesianisch hat die Lohnsetzungskurve einen <b>horizontalen Abschnitt</b>: In einem breiten Bereich führt mehr Beschäftigung nicht zu höheren Lohnforderungen. Entsprechend hat auch die kurzfristige Phillips-Kurve einen horizontalen Abschnitt. Mehr Beschäftigung ist dort ohne steigende Inflation möglich, es gibt keine eindeutige NAIRU.</p>
<p><b>Einkommenspolitik</b>: Arbeitgeber:innen und Arbeitnehmer:innen verzichten, unter Druck oder Vermittlung der Regierung, auf Lohn-Preis-Spiralen und machen so den Weg frei für mehr Beschäftigung ohne Inflation.</p>
<h3>Vergleich mit dem Neukeynesianismus</h3>
${cmp([["","Neukeynesianismus","Postkeynesianismus"],["NAIRU","eindeutig","keine eindeutige (horizontaler Abschnitt)"],["Mehr Beschäftigung ohne Inflation durch","Angebotsreformen (Deregulierung)","Nachfragepolitik, gestützt durch Einkommenspolitik"]])}`,
check:[{q:"Welche Politik empfiehlt der Postkeynesianismus, um mehr Beschäftigung ohne Inflation zu erreichen?", o:["Deregulierung des Arbeitsmarkts","Einkommenspolitik und Nachfragepolitik","Höhere Zinsen","Ausgeglichene Haushalte"], a:1, ex:"Sozialpartner verzichten unter Vermittlung der Regierung auf Lohn-Preis-Spiralen.", w:["Deregulierung ist die Antwort des Neuen Konsenses.", null, "Höhere Zinsen würden die Beschäftigung senken.", "Ausgeglichene Haushalte widersprechen der Functional Finance des Postkeynesianismus."]}]},
{id:"7-6", t:"Das Kostenparadox mit Kalecki", html:`
<p>Postkeynesianisch hängt die Nachfrage von der Verteilung ab. Kaleckianische Konsumfunktion mit unterschiedlichen Konsumneigungen aus Löhnen und Gewinnen:</p>
<div class="eq">C = a<sub>W</sub> + a<sub>Π</sub> + b<sub>W</sub>W + b<sub>Π</sub>Π,   W = w·Y,   Π = (1 − w)·Y</div>
${bsp("Beispiel der Vorlesung",[["Gegeben","a_W = 60, a_Π = 40, b_W = 0,9, b_Π = 0,5, I = 100, Lohnanteil w = 0,6"],["Rechnung","$ Y* = 200 / (1 − 0,9 · 0,6 − 0,5 · 0,4) = 200 / 0,26 ≈ 769,23"],["Lohnanteil 0,7","$ Y* = 200 / (1 − 0,63 − 0,15) = 200 / 0,22 ≈ 909,09"],["Deutung","Mehr Einkommen geht an die, die mehr davon ausgeben. Die Nachfrage steigt."]])}
${bsp("Mit Investitionen I = 100 + 0,12Y (Aufgabenblatt 7)",[["Lohnanteil 0,6","$ Y* = 200 / 0,14 ≈ 1428,57\n$ Π = 0,4 · 1428,57 ≈ 571,43"],["Lohnanteil 0,7","$ Y* = 200 / 0,10 = 2000\n$ Π = 0,3 · 2000 = 600"],["Ergebnis","Die Gewinne steigen, obwohl die Unternehmen höhere Löhne zahlen."]])}
<div class="merk"><b>Kostenparadox</b>Alle Unternehmen zahlen höhere Löhne, und trotzdem steigen die gesamtwirtschaftlichen Gewinne, weil die Nachfrage stärker wächst. Basis ist die höhere Konsumneigung aus Löhnen.</div>`,
check:[{q:"Worauf beruht das Kostenparadox?", o:["Auf sinkenden Zinsen","Auf der höheren Konsumneigung aus Löhnen als aus Gewinnen","Auf steigenden Exporten","Auf höherer Produktivität"], a:1, ex:"Umverteilung zu den Löhnen erhöht die durchschnittliche Konsumneigung und damit die Nachfrage.", w:["Zinsen kommen im Kalecki-Modell der Vorlesung nicht vor.", null, "Exporte erhöhen Gewinne auch, erklären aber nicht das Kostenparadox.", "Die Produktivität bleibt im Beispiel gleich. Es ändert sich nur die Verteilung."]}]}
];

LESSONS[8]=[
{id:"8-1", t:"Spielarten des Kapitalismus", html:`
<p>Warum sind Arbeits- und Finanzmärkte in manchen Ländern stärker reguliert? Warum ist die Geld- und Fiskalpolitik in manchen Ländern keynesianischer als in anderen? Die Vergleichende Politische Ökonomie unterscheidet:</p>
${cmp([["","Koordinierte Marktwirtschaft (CME)","Liberale Marktwirtschaft (LME)"],["Beispiele","Deutschland, Niederlande, Skandinavien, Japan","USA, Vereinigtes Königreich"],["Produktion","schrittweise Innovation, spezifische Qualifikationen, Kündigungsschutz, geduldige Finanzierung über Banken, Mitbestimmung, Exportorientierung","radikale Innovation, allgemeine Qualifikationen, hire and fire, Finanzierung über den Kapitalmarkt, Shareholder Value"],["Wohlfahrtsstaat","sozialdemokratisch/kontinental, duale Ausbildung","liberal, minimal, College"],["Politisches System","Konsens, Verhältniswahlrecht, Koalitionen","Mehrheitswahlrecht, Ein-Parteien-Regierungen"],["Nachfragesteuerung","regelbasiert, neoklassisch, konservativ","diskretionär, keynesianisch, offensiv"]])}
<h3>Warum?</h3>
<div class="dlist"><b>CME</b><span>Die exportorientierte Industrie ist auf preisliche Wettbewerbsfähigkeit angewiesen, die Geld- und Fiskalpolitik soll Inflation vermeiden. Ein starker Sozialstaat sichert ab.</span><b>LME</b><span>Die soziale Sicherung ist schwach, deshalb ist expansive Politik nötig, um längere Arbeitslosigkeit zu vermeiden. Externe Wettbewerbsfähigkeit ist weniger wichtig.</span></div>
<p>Empirisch schwanken in den USA Arbeitslosenquote, staatlicher Finanzierungssaldo und Leitzinsen stärker als in Deutschland.</p>`,
check:[{q:"Welche makroökonomische Politik ist in einer CME zu erwarten?", o:["Diskretionär und keynesianisch","Regelbasiert und konservativ","Keine Geldpolitik","Dauerhafte Defizite"], a:1, ex:"Regelbasiert und konservativ: Die exportorientierte Industrie braucht Preisstabilität und Wettbewerbsfähigkeit.", w:["Diskretionär und keynesianisch ist die Politik in liberalen Marktwirtschaften wie den USA.", null, "Auch CMEs haben Geldpolitik, sie ist nur auf Preisstabilität ausgerichtet.", "Dauerhafte Defizite passen nicht zur konservativen Fiskalpolitik der CMEs."]}]},
{id:"8-2", t:"Wachstumsmodelle: vom Fordismus zur Finanzialisierung", html:`
<p><b>Fordismus (1945–1970er)</b>: lohngetriebenes Wachstum. Steigende Löhne tragen den Massenkonsum, Investitionen und Gewinne wachsen im Gleichschritt. Regulierte Finanzmärkte, wenig Spielraum für private oder Auslandsverschuldung, keynesianische Fiskalpolitik.</p>
<p><b>Krise (1970er)</b>: „zu hohe Löhne“. Zwei Deutungen:</p>
<ul><li><b>Regimewechsel</b> von lohngetriebenem <span class="pz">(wage-led)</span> zu gewinngetriebenem <span class="pz">(profit-led)</span> Wachstum, weil hohe Lohnkosten die Investitionen belasten.</li><li><b>Politischer Widerstand</b> der Kapitalseite gegen an Vollbeschäftigung gewöhnte Gewerkschaften. Mitterrand wollte 1981–83 einen Übergang zum Sozialismus, Thatcher und Reagan wollten die Macht der Gewerkschaften brechen.</li></ul>
<p>Es folgte der Neoliberalismus.</p>
<p><b>Neoliberalismus und Finanzialisierung (1980–2008)</b>: Die Löhne der Mittelschicht fallen als Basis der Konsumnachfrage aus, Investitionen leiden unter der Shareholder-Value-Orientierung. Zwei „Lösungen“:</p>
<ul><li><b>Schuldengetriebenes Wachstum</b> (debt-led), USA, Vereinigtes Königreich: Untere Einkommensgruppen verschulden sich für Konsum, dazu Staats- und Leistungsbilanzdefizite.</li>
<li><b>Exportorientiertes Wachstum</b> (export-led), Deutschland, Japan, China: Lohnzurückhaltung, Unternehmensersparnis und Staatsüberschüsse schwächen die Binnennachfrage, Leistungsbilanzüberschüsse.</li></ul>
<p><b>Krise seit 2008</b>: Schuldenkrise der privaten Haushalte (USA, UK) und Schuldenkrise bei den Handelspartnern der Exportländer.</p>`,
check:[
 {q:"Was kennzeichnet ein schuldengetriebenes Wachstumsmodell?", o:["Lohnzurückhaltung und Exportüberschüsse","Konsum unterer Einkommensgruppen auf Kredit","Staatliche Überschüsse","Steigende Lohnquote"], a:1, ex:"Untere Einkommensgruppen halten ihren Konsum über Kredite, typisch für die USA vor 2008.", w:["Lohnzurückhaltung und Exportüberschüsse kennzeichnen das exportgetriebene Modell.", null, "Im schuldengetriebenen Modell hat auch der Staat eher Defizite.", "Gerade nicht: Weil die Löhne stagnieren, wird auf Kredit konsumiert."]},
 {q:"Was kennzeichnet ein exportgetriebenes Wachstumsmodell?", o:["Leistungsbilanzdefizite","Lohnzurückhaltung, schwache Binnennachfrage, Leistungsbilanzüberschüsse","Hohe Haushaltsverschuldung","Expansive Fiskalpolitik"], a:1, ex:"Lohnzurückhaltung, schwache Binnennachfrage und Leistungsbilanzüberschüsse, typisch für Deutschland.", w:["Leistungsbilanzdefizite haben die schuldengetriebenen Länder.", null, "Hohe Haushaltsverschuldung ist typisch für das schuldengetriebene Modell.", "Exportgetriebene Länder haben eher Staatsüberschüsse."]}
]},
{id:"8-3", t:"Kaleckis Gewinngleichung", html:`
<p>Aus Y = C<sub>W</sub> + C<sub>Π</sub> + I + G + X − M und Y = W<sub>netto</sub> + Π<sub>netto</sub> + T folgt:</p>
<div class="eq">Π<sub>netto</sub> = C<sub>Π</sub> + I − S<sub>W</sub> + (G − T) + (X − M)</div>
<p>mit S<sub>W</sub> = W<sub>netto</sub> − C<sub>W</sub>, der Ersparnis aus Löhnen. Teilt man durch den Kapitalstock K, erhält man die Profitrate r = Π/K und die Akkumulationsrate g = I/K.</p>
<p>Ausgangspunkt postkeynesianischer Wachstums- und Verteilungsmodelle sind die <b>„Gewinne ohne Investitionen“</b> im neoliberalen Zeitalter. Die Lücke r − g kann steigen, wenn</p>
<ul><li>mehr Gewinne ausgeschüttet und daraus konsumiert wird (USA),</li>
<li>die Ersparnis aus Löhnen sinkt oder negativ wird (debt-led, USA),</li>
<li>die Nettoexporte steigen (export-led, Deutschland).</li></ul>`,
check:[{q:"Nach Kaleckis Gewinngleichung: Was erhöht die Gewinne, ohne dass investiert wird?", o:["Höhere Ersparnis aus Löhnen","Höhere Nettoexporte","Höhere Steuern","Sinkende Staatsausgaben"], a:1, ex:"Die Nettoexporte X − M stehen mit Plus in der Gewinngleichung. Steigen sie, steigen die Gewinne, auch ohne Investitionen.", w:["S_W steht mit Minus in der Gleichung: Mehr Ersparnis aus Löhnen senkt die Gewinne.", null, "T steht mit Minus in (G − T): Höhere Steuern senken die Gewinne.", "G steht mit Plus: Sinkende Staatsausgaben senken die Gewinne."]}]},
{id:"8-4", t:"Ungleichheit und Krise", html:`
<p>In den USA stieg der Anteil der oberen 10 %, 1 % und 0,1 % an den Haushaltseinkommen seit den 1980ern stark. Gleichzeitig fiel die Sparquote der Haushalte, und ihre Verschuldung stieg auf weit über 100 % des verfügbaren Einkommens. Die Nachfrage der Mittelschicht hielt sich über Kredit, bis die Schuldenkrise 2007 ausbrach.</p>
<p>In Deutschland sank der Anteil der verfügbaren Haushaltseinkommen am Gesamteinkommen, Unternehmen und Staat steigerten ihre Anteile. Seit etwa 2000 haben Haushalte und Unternehmen, seit etwa 2010 auch der Staat positive Finanzierungssalden. Nach der Salden-Identität muss sich dann das Ausland verschulden: Die schwache Binnennachfrage zeigt sich in Exportüberschüssen.</p>
<div class="merk"><b>Für den Essay</b>Die Verbindung von Verteilung (funktional, sektoral, personell) und Wachstumsmodell erklärt, warum hohe Ungleichheit postkeynesianisch als Krisenursache gilt: Entweder fehlt Nachfrage, oder sie entsteht über Verschuldung im Inland oder im Ausland.</div>`,
check:[{q:"Wie hängen in den USA Ungleichheit und Krise 2007 zusammen?", o:["Gar nicht","Die Mittelschicht hielt ihren Konsum über Verschuldung, bis die Schuldenkrise kam","Steigende Löhne lösten die Krise aus","Exportüberschüsse führten zur Krise"], a:1, ex:"Schuldengetriebenes Wachstum: Die Sparquote sank, die Verschuldung stieg, bis die private Schuldenkrise ausbrach.", w:["Die Vorlesung sieht einen engen Zusammenhang: Ungleichheit schwächt die Nachfrage der Mittelschicht.", null, "Die Löhne der Mittelschicht stagnierten gerade.", "Die USA hatten Leistungsbilanzdefizite, keine Überschüsse."]}]}
];

CARDS[6]=[
 {id:"c6-01", f:"Wie entstehen Lohn-Preis-Spiralen?", b:"1. Die Beschäftigung liegt über dem Gleichgewicht (NAIRU).\n2. Arbeitnehmer:innen fordern die erwartete Inflation plus die Reallohnlücke (Differenz zwischen gefordertem und gezahltem Reallohn).\n3. Die Unternehmen erhöhen die Preise entsprechend.\nFolge: Die Inflation beschleunigt sich, die Reallöhne bleiben konstant."},
 {id:"c6-02", f:"Neoklassische Synthese: Grundidee", b:"| | Kurze Frist | Lange Frist\n| Sicht | keynesianisch | neoklassisch (flexible Preise, S bestimmt I)\nVertreter: Samuelson, Hicks\nZeit: Mainstream von 1945 bis Anfang der 1970er"},
 {id:"c6-03", f:"Ursprüngliche und modifizierte Phillips-Kurve", b:"Ursprünglich: Je geringer die Arbeitslosigkeit, desto schneller steigen die Nominallöhne.\nModifiziert: Je geringer die Arbeitslosigkeit, desto höher die Preisinflation.\n$ π = f(U)"},
 {id:"c6-04", f:"„5 % Inflation sind mir lieber als 5 % Arbeitslosigkeit“", b:"Helmut Schmidt, 1970er Jahre\nIdee: ein **dauerhafter Zielkonflikt** entlang der Phillips-Kurve. Die Politik kann mehr Inflation für weniger Arbeitslosigkeit wählen.\nMonetarismus und Neuklassik bestreiten das später."},
 {id:"c6-05", f:"Natürliche Arbeitslosigkeit (NAIRU)", b:"Definition: die Arbeitslosenquote, bei der sich die Inflation **nicht beschleunigt**\nGrafik: Die langfristige Phillips-Kurve ist dort vertikal.\nUrsachen: zu hohe Löhne, Rigiditäten (z. B. Kündigungsschutz, Tarifbindung, hohe Arbeitslosenunterstützung)"},
 {id:"c6-06", f:"Friedmans Erklärung der vertikalen Phillips-Kurve", b:"1. Kurzfristig werden Arbeitnehmer:innen über die Inflation getäuscht: Sie halten höhere Nominallöhne für höhere Reallöhne.\n2. Die höhere Inflation wird künftig erwartet.\n3. Die kurzfristige Phillips-Kurve verschiebt sich nach oben.\nLangfristig müssen die Erwartungen erfüllt sein, die Kurve ist vertikal."},
 {id:"c6-07", f:"Stagflation", b:"Stagnation (Stillstand) bei gleichzeitiger Inflation\nZeit: 1970er, nach den Ölpreisschocks\nErklärung des Monetarismus: Nachfragepolitik über die natürliche Arbeitslosigkeit hinaus"},
 {id:"c6-08", f:"„Irrelevanz der Wirtschaftspolitik“", b:"Folgerung von Monetarismus und Neuklassik:\n- keine diskretionäre Konjunkturpolitik\n- regelgebundene Politik (z. B. festes Inflationsziel)\n- Ricardianische Äquivalenz: Multiplikator nahe null\n- Flexibilisierung der Märkte"},
 {id:"c6-09", f:"Lohnsetzung und Preissetzung", b:"Lohnsetzung (steigend): der Reallohn, den Arbeitnehmer:innen je nach Beschäftigung fordern\nPreissetzung (waagerecht): der Reallohn, den Unternehmen zu zahlen bereit sind\nSchnittpunkt: Gleichgewicht, die NAIRU"},
 {id:"c6-10", f:"Neuer Konsens: lang- und kurzfristig", b:"| | Kurzfristig | Langfristig\n| Was zählt? | die Nachfrage | der Arbeitsmarkt\n| Politik | aktive Konjunkturpolitik, vor allem über die Geldpolitik | Angebotspolitik\n| Gleichgewicht | Y* = 1/(1 − c₁) · (…) | Y* = Y_POT"},
 {id:"c6-11", f:"Wirtschaftspolitischer Mainstream vor der Krise", b:"- Angebotsorientierung: Politik setzt bei Produktion und Arbeitsmarkt an, z. B. durch Flexibilisierung.\n- Passive Fiskalpolitik: Stabilitäts- und Wachstumspakt der EU, Schuldenbremse\n- Aktive Geldpolitik: Steuerung über ein Inflationsziel (Inflation Targeting), bei der EZB unter, aber nahe 2 %"},
 {id:"c6-12", f:"Langfristige Gleichgewichtsbedingung im Neuen Konsens", b:"$ Y* = Y_POT\nSonst droht eine Inflations- oder Deflationsspirale (sich selbst verstärkender Anstieg oder Verfall der Preise).\nDie Zentralbank wählt den Zins so, dass das erreicht wird."},
 {id:"c6-13", f:"Zinsregel beim Inflation Targeting", b:"$ iₜ = iₜ₋₁ + k · (πₜ₋₁ − πᵀ),  k > 0\nInflation über dem Ziel: Zins rauf\nInflation unter dem Ziel: Zins runter\nBeispiel: iₜ₋₁ = 2 %, k = 1, Inflation 4 %, Ziel 2 % ⇒ iₜ = 4 %"},
 {id:"c6-14", f:"Steuerung über ein Inflationsziel (Inflation Targeting): welche Denkschule, welche Rolle der Fiskalpolitik?", b:"Denkschule: Neuer Konsens (Neue Neoklassische Synthese)\nFiskalpolitik: passiv\nGeldpolitik: stabilisiert die Inflation und schließt damit die Output-Lücke"},
 {id:"c6-15", f:"Konjunkturprogramm mit Y* > Y_POT im Neuen Konsens", b:"1. Die Beschäftigung liegt über dem Gleichgewicht (NAIRU).\n2. Zwischen Lohn- und Preissetzung klafft eine Lücke.\n3. Die kurzfristige Phillips-Kurve verschiebt sich Periode für Periode nach oben: steigende Inflation.\nReaktion: Die Zentralbank muss den Zins erhöhen."},
 {id:"c6-16", f:"Angebotspolitik über die Lohnsetzung", b:"Maßnahme: Deregulierung, z. B. geringere Arbeitslosenunterstützung, weniger Flächentarifverträge\nWirkung: Die Lohnsetzungsmacht sinkt. Lohnsetzungskurve und langfristige Phillips-Kurve verschieben sich nach rechts.\nErgebnis: Y_POT steigt, mehr Beschäftigung ohne Inflation"},
 {id:"c6-17", f:"Angebotspolitik über die Preissetzung", b:"Ziel: Die Preissetzungskurve verschiebt sich nach oben.\nWege:\n- bessere Ausbildung und höhere Produktivität (Arbeitgeber:innen zahlen höhere Reallöhne)\n- mehr Wettbewerb auf dem Gütermarkt (niedrigere Preise)"},
 {id:"c6-18", f:"Neoklassische vs. keynesianische Arbeitslosigkeit: wo bekämpfen?", b:"| | Neoklassisch | Keynesianisch\n| Ursache | Arbeitsmarkt (zu hohe Löhne, Rigiditäten) | zu geringe Güternachfrage\n| Bekämpfung | auf dem Arbeitsmarkt | über die Nachfrage"},
 {id:"c6-19", f:"Warum braucht eine Währungsunion Fiskalpolitik?", b:"Die gemeinsame Geldpolitik (EZB) kann **nicht länderspezifisch** steuern: Ein Zins gilt für alle.\nDiese Rolle müsste die nationale Fiskalpolitik übernehmen."}
];
CARDS[7]=[
 {id:"c7-01", f:"Begründer:innen des Postkeynesianismus", b:"Joan Robinson, Nicholas Kaldor\nOrt und Zeit: Cambridge, 1950er und 1960er\nGrundlage: Keynes und Michał Kalecki"},
 {id:"c7-02", f:"„Bastard-Keynesianismus“", b:"Abwertender Begriff (Joan Robinson) für Neoklassische Synthese und Neuen Konsens.\nVorwurf: Sie reduzieren Keynes auf die **kurze Frist**. Langfristig gilt bei ihnen wieder die Neoklassik."},
 {id:"c7-03", f:"Functional Finance", b:"Die Fiskalpolitik spielt die **zentrale Rolle** gegen Arbeitslosigkeit.\nStaatsverschuldung ist kein Hindernis für Vollbeschäftigungspolitik."},
 {id:"c7-04", f:"Hysterese: Definition", b:"Ein Zustand dauert fort, auch wenn die Anregung weggefallen ist.\nMakro: Kurzfristiger Nachfragemangel führt zu dauerhaft geringerem Produktionspotenzial."},
 {id:"c7-05", f:"Hysterese im Arbeitsmarktdiagramm", b:"- Lohnsetzung verschiebt sich nach oben: Langzeitarbeitslose üben keinen Lohndruck mehr aus.\n- Preissetzung verschiebt sich nach unten: Die Produktivität sinkt durch fehlende Investitionen.\nErgebnis: Gleichgewichtige Beschäftigung und Potenzial sinken."},
 {id:"c7-06", f:"Hysterese-Gefahr durch Austerität", b:"1. Im Abschwung liegt ein konjunkturelles Problem vor (vorübergehende Nachfrageschwäche).\n2. Die Politik deutet es fälschlich als strukturell (dauerhaftes Angebotsproblem).\n3. Sie reagiert mit Sparpolitik (Austerität) und Deregulierung.\nFolge: Das Problem wird tatsächlich strukturell."},
 {id:"c7-07", f:"Randwertproblem", b:"Potenzial und NAIRU (strukturelle Arbeitslosigkeit) werden aus den beobachteten Daten geschätzt.\nAm aktuellen Rand folgen die Schätzungen den neuen Daten.\nFolge: Ein Abschwung erscheint strukturell, die Output-Lücke klein.\nBeispiel: Spanien 2007 bis 2013, geschätzte strukturelle Arbeitslosigkeit von unter 10 % auf über 25 %"},
 {id:"c7-08", f:"Wie verhält sich das BIP bei positiver Output-Lücke zum Potenzial?", b:"Das beobachtete BIP liegt **über** dem (geschätzten) Produktionspotenzial.\nGegenstück: Bei negativer Lücke liegt es darunter."},
 {id:"c7-09", f:"Postkeynesianische Phillips-Kurve", b:"Die Lohnsetzung und die kurzfristige Phillips-Kurve haben einen **horizontalen Abschnitt**.\nDort ist mehr Beschäftigung ohne steigende Inflation möglich.\nEs gibt keine eindeutige NAIRU."},
 {id:"c7-10", f:"Einkommenspolitik", b:"Gewerkschaften und Arbeitgeberverbände verzichten unter Druck oder Vermittlung der Regierung auf Lohn-Preis-Spiralen.\nZiel: mehr Beschäftigung ohne Inflation\nGegenstück im Neuen Konsens: Deregulierung"},
 {id:"c7-11", f:"Kaleckianische Konsumfunktion", b:"$ C = a_W + a_Π + b_W · W + b_Π · Π\nb_W > b_Π: Aus Löhnen wird ein größerer Anteil konsumiert als aus Gewinnen.\nFolge: Die Verteilung beeinflusst die Nachfrage."},
 {id:"c7-12", f:"Basis des Kostenparadoxes", b:"Basis: die **höhere Konsumneigung aus Löhnen**\nWirkung: Ein höherer Lohnanteil erhöht Nachfrage und Einkommen.\nParadox: Trotz höherer Lohnkosten können die Gewinne steigen.\nBeispiel (Aufgabenblatt 7): Lohnanteil 0,6 → 0,7, Gewinne ≈ 571 → 600"},
 {id:"c7-13", f:"Gründe für Zweifel an der Geldpolitik (postkeynesianisch)", b:"Investitionen und Konsum hängen mehr ab von\n- der Stimmung der Unternehmen (animal spirits),\n- sozialen Normen (z. B. was als angemessener Lebensstandard gilt),\n- Institutionen (z. B. Tarifsystem, Bankenregulierung),\n- der Einkommensverteilung\nals vom Zins. Dazu kommen Nominalzins- und Investitionsfalle, und die Output-Lücke ist nicht seriös messbar."}
];
CARDS[8]=[
 {id:"c8-01", f:"Koordinierte Marktwirtschaft (CME): Merkmale", b:"- regulierte Arbeitsbeziehungen und Unternehmensführung (z. B. Mitbestimmung im Aufsichtsrat)\n- Korporatismus: Staat, Gewerkschaften und Arbeitgeber stimmen sich ab.\n- ausgebauter Sozialstaat, geringe Ungleichheit\n- konservative Geld- und Fiskalpolitik\nBeispiele: Deutschland, Skandinavien, Japan"},
 {id:"c8-02", f:"Liberale Marktwirtschaft (LME): Merkmale", b:"- wenig regulierte Arbeits- und Finanzmärkte\n- Ausrichtung auf den Wert für die Aktionär:innen (Shareholder Value)\n- kleiner Sozialstaat, hohe Ungleichheit\n- offensivere Geld- und Fiskalpolitik\nBeispiele: USA, Vereinigtes Königreich"},
 {id:"c8-03", f:"Warum betreiben CMEs konservative Makropolitik?", b:"- Die exportorientierte Industrie braucht **preisliche Wettbewerbsfähigkeit**, also keine Inflation.\n- Ein starker Sozialstaat federt Arbeitslosigkeit ab.\nBeispiel: Deutschland"},
 {id:"c8-04", f:"Warum betreiben LMEs expansive Makropolitik?", b:"- Die soziale Sicherung ist schwach: Längere Arbeitslosigkeit muss durch **Nachfragepolitik** vermieden werden.\n- Externe Wettbewerbsfähigkeit ist weniger wichtig.\nBeispiel: USA"},
 {id:"c8-05", f:"Fordismus", b:"Zeit: 1945 bis 1970er\n- lohngetriebenes Wachstum: Steigende Löhne tragen die Nachfrage.\n- Massenkonsum; Investitionen und Gewinne wachsen im Gleichschritt\n- regulierte Finanzmärkte\n- keynesianische Fiskalpolitik"},
 {id:"c8-06", f:"Zwei Deutungen der Krise der 1970er", b:"- Regimewechsel: von lohngetriebenem (wage-led) zu gewinngetriebenem (profit-led) Wachstum, weil hohe Lohnkosten die Investitionen belasten\n- Politischer Widerstand: Die Kapitalseite wehrt sich gegen starke Gewerkschaften (Thatcher, Reagan).\nDanach: Neoliberalismus"},
 {id:"c8-07", f:"Schuldengetriebenes Wachstum (debt-led)", b:"Beispiele: USA, Vereinigtes Königreich\n- Untere Einkommensgruppen konsumieren auf Kredit.\n- Staatsdefizite\n- Leistungsbilanzdefizite"},
 {id:"c8-08", f:"Exportgetriebenes Wachstum (export-led)", b:"Beispiele: Deutschland, Japan, China\n- Lohnzurückhaltung (bewusst geringe Lohnsteigerungen)\n- Unternehmensersparnis und Staatsüberschüsse\n- schwache Binnennachfrage\n- Leistungsbilanzüberschüsse"},
 {id:"c8-09", f:"Kaleckis Gewinngleichung", b:"$ Π_netto = C_Π + I − S_W + (G − T) + (X − M)\nC_Π: Konsum aus Gewinnen\nS_W: Ersparnis aus Löhnen\nMit Plus wirken: Konsum aus Gewinnen, Investitionen, Staatsdefizit, Nettoexporte"},
 {id:"c8-10", f:"„Gewinne ohne Investitionen“: drei Kanäle", b:"- Mehr Konsum aus Gewinnen: Gewinne werden an Eigentümer:innen ausgeschüttet und ausgegeben (USA).\n- Sinkende Ersparnis aus Löhnen: Haushalte verschulden sich (debt-led, USA).\n- Steigende Nettoexporte (export-led, Deutschland)"},
 {id:"c8-11", f:"Ungleichheit und Krise 2007 in den USA", b:"1. Die Top-Einkommensanteile steigen (Anteil der Reichsten am Gesamteinkommen).\n2. Die Mittelschicht hält ihren Konsum: Die Sparquote sinkt, die Verschuldung steigt.\n3. 2007 bricht die private Schuldenkrise aus."},
 {id:"c8-12", f:"Verteilung und deutsche Exportüberschüsse", b:"- Der Anteil der Haushaltseinkommen am Gesamteinkommen sinkt.\n- Haushalte, Unternehmen und (seit etwa 2010) der Staat haben Überschüsse.\nNach der Salden-Identität muss sich das **Ausland** verschulden: Die schwache Binnennachfrage zeigt sich in Exportüberschüssen."}
];

